// 1. Leer los campos exactos del formulario
const formData = $input.first().json;

const nombreServidor = formData["Servidor"] || "srv-nodo-01";
const rolRaw = String(formData["Rol"] || "WEB").trim().toUpperCase();
const macAddress = formData["Direccion MAC"] || "00:1A:2B:3C:4D:99";
const solicitante = formData["Solicitante"] || "Admin";

// 2. Definir rangos de subred por Rol (192.168.10.0/24)
const subredBase = "192.168.10.";
const gateway = "192.168.10.1";
const mascara = "255.255.255.0";

const rangosPorRol = {
  "WEB": { inicio: 10,  fin: 50 },
  "DB":  { inicio: 51,  fin: 100 },
  "APP": { inicio: 101, fin: 150 }
};

// Seleccionar el rango (si no coincide, usa WEB por defecto)
const rango = rangosPorRol[rolRaw] || rangosPorRol["WEB"];

// 3. Base de datos IPAM simulada (IPs ocupadas)
const ipamOcupadas = [
  { ip: "192.168.10.10", hostname: "srv-web-01", mac: "00:1A:2B:3C:4D:10", rol: "WEB" },
  { ip: "192.168.10.11", hostname: "srv-web-02", mac: "00:1A:2B:3C:4D:11", rol: "WEB" }
];

// 4. Buscar la primera IP libre en el rango del Rol elegido
const listaIpsOcupadas = ipamOcupadas.map(r => r.ip);
let ipAsignada = null;

for (let octeto = rango.inicio; octeto <= rango.fin; octeto++) {
  const ipCandidata = `${subredBase}${octeto}`;
  if (!listaIpsOcupadas.includes(ipCandidata)) {
    ipAsignada = ipCandidata;
    break;
  }
}

if (!ipAsignada) {
  throw new Error(`No hay IPs disponibles para el rol ${rolRaw}`);
}

// 5. Actualizar inventario IPAM
const nuevoRegistro = {
  ip: ipAsignada,
  hostname: nombreServidor,
  mac: macAddress,
  rol: rolRaw,
  solicitante: solicitante,
  estado: "Asignada"
};

const ipamActualizado = [...ipamOcupadas, nuevoRegistro];

// 6. Comando nativo para Windows (registra el DNS local por SSH)
const comandoDnsWindows = `cmd /c "echo ${ipAsignada} ${nombreServidor}.local ${nombreServidor} >> C:\\Users\\Public\\hosts_dns_ipam.txt && echo ${ipAsignada} ${nombreServidor}.local ${nombreServidor}"`;

return [
  {
    json: {
      mensaje: `Servidor ${nombreServidor} provisionado con éxito.`,
      ip_asignada: ipAsignada,
      gateway: gateway,
      mascara: mascara,
      nombre_servidor: nombreServidor,
      mac_address: macAddress,
      rol: rolRaw,
      solicitante: solicitante,
      comando_dns: comandoDnsWindows,
      inventario_ipam: ipamActualizado
    }
  }
];

